from lib import *
S = SS('j251')
steps = [
    step("同一个原始异常 IllegalStateException(\"boom\") 在不同位置被观察到时形状不同(JDK 21):supplyAsync 里抛出,handle 拿到的是 CompletionException(原因 IllegalStateException:boom),join() 抛出 CompletionException,get() 抛出 ExecutionException;用 completeExceptionally(原始异常) 完成的 future,handle 拿到的是原始的 IllegalStateException,但它的下游 thenApply 的 future 拿到的是 CompletionException(原因 boom),它自己的 join() 抛 CompletionException、get() 抛 ExecutionException。thenApply 里抛出的异常在 handle 里也是 CompletionException。exceptionally 在 supplyAsync 的 future 上收到的类型是 CompletionException(不是原始异常),在 completeExceptionally 的 future 上收到的才是 IllegalStateException。", t=tl(S(1)), done=lidx(S(1), 'supplyAsync 里抛出:handle', 'join() 抛出', 'get() 抛出'), mark=lidx(S(1), 'completeExceptionally(原始异常) 的那个 future', '它的下游 thenApply', 'thenApply 里抛出', 'exceptionally 在 supplyAsync', 'exceptionally 在 completeExceptionally'), kv=KV([['supplyAsync 抛出 / thenApply 抛出 / 下游阶段', '回调拿到 CompletionException(原因 = 原始异常)'], ['completeExceptionally 的那个 future 自己', '回调拿到原始异常'], ['join() / get()', 'CompletionException / ExecutionException']], ['supplyAsync 抛出 / thenApply 抛出 / 下游阶段'])),
    step("没人观察的异常:runAsync 里抛出异常、没有 join 也没有 handle:isCompletedExceptionally() = true,默认的 UncaughtExceptionHandler 被调用 0 次,标准错误里没有任何堆栈(这个进程到这里没有任何异常输出);thenRun 链上的后续阶段也失败了但没有被执行,同样没有任何输出。对照:ExecutorService.execute 里抛出的异常,默认 UncaughtExceptionHandler 被调用 1 次。CompletableFuture 把异常存进了 future,不观察就看不到。", t=tl(S(2)), done=lidx(S(2), 'runAsync 抛出异常、没有 join', 'thenRun 链上的后续阶段'), mark=lidx(S(2), '对照:ExecutorService.execute'), kv=KV([['runAsync 抛出、没人 join', '0 次 handler、没有任何输出'], ['execute 抛出', 'UncaughtExceptionHandler 被调用 1 次']], ['runAsync 抛出、没人 join'])),
    step("whenComplete / handle / exceptionally:whenComplete(只观察)在失败的 future 上,结果仍然失败;whenComplete 的回调在成功的 future 上抛出 RuntimeException(\"B\"),结果变成 CompletionException(原因 B);在失败的 future(原异常 A)上回调又抛出 B,结果的异常仍是 CompletionException(原因 A),B 没有出现在结果里。handle((v, e) -> e != null ? -1 : v) = -1,exceptionally(e -> -2) = -2,JDK 12 的 exceptionallyCompose 用另一个 future 恢复得到 77。handle 回调自己抛异常:结果是 CompletionException(原因 C)。", t=tl(S(3)), done=lidx(S(3), 'whenComplete(只观察)在失败的 future 上', '成功的 future 上抛出'), mark=lidx(S(3), '失败的 future 上又抛出 B', 'handle 可以恢复', 'exceptionallyCompose', 'handle 回调自己抛异常'), kv=KV([['whenComplete', '不改变结果;回调在成功时抛出会让结果失败;失败时抛出的 B 被丢掉'], ['handle / exceptionally / exceptionallyCompose', '可以恢复成值或另一个 future']], ['whenComplete'])),
    step("allOf 不会快速失败:fast 在 100 ms 失败,slow 要 1000 ms,300 ms 时 fast 已失败但 allOf 还没完成;all.join() 在 1006 ms 时才抛出 CompletionException(原因 “100 ms 时失败”)。anyOf 取第一个完成者,包括失败的:一个 100 ms 失败、一个 400 ms 成功,anyOf 在 110 ms 就以 CompletionException(原因 “先失败的”)完成,后面成功的结果被忽略。", t=tl(S(4)), done=lidx(S(4), '300 ms 时:fast 已失败'), mark=lidx(S(4), 'all.join() 在', 'anyOf 的结果在'), b=bars([['fast 失败', 100, '100 ms'], ['allOf 抛出', 1006, '1006 ms'], ['anyOf 以失败完成', 110, '110 ms']], 1006, done=[0, 1, 2]), kv=KV([['allOf', '一个在 100 ms 失败,仍等到 1006 ms 才抛出'], ['anyOf', '第一个完成的是失败的,110 ms 就失败']], ['allOf'])),
    step("cancel 与 orTimeout 不会停止底层任务:对运行中的 supplyAsync 调 cancel(true) 返回 true、isCancelled() = true,但底层任务照常跑完(sleep 600 ms,没有被中断),下游 thenApply 的结果是 CompletionException(原因 CancellationException)。orTimeout(200 ms) 在 211 ms 时让 join() 抛 CompletionException(原因 TimeoutException),700 ms 后底层任务仍然执行完了。completeOnTimeout(\"fallback\", 200 ms) 返回 fallback。取消与超时只改变 future 的状态,没有改变线程里的任务。", t=tl(S(5)), done=lidx(S(5), 'cancel(true) 返回 true'), mark=lidx(S(5), 'orTimeout(200 ms)', '700 ms 后底层任务', 'completeOnTimeout'), kv=KV([['cancel(true)', 'future 取消,任务照常跑完,未被中断'], ['orTimeout(200 ms)', '211 ms 抛 TimeoutException,任务仍跑完']], ['cancel(true)'])),
]
A = mkartj('j251', 251, 'Java,并发,CompletableFuture,异常处理,CompletionException,allOf,真实验证,动画演示',
    '在 JDK 21 上实测 CompletableFuture 的异常:同一个异常在 handle / join / get / exceptionally 里的形状(CompletionException、ExecutionException、原始异常)不同;没人观察的异常不产生任何输出;whenComplete 里再抛的异常被丢掉;allOf 在 100 ms 失败后仍等到 1006 ms 才抛出;cancel 与 orTimeout 不会停止底层任务。',
    'CompletableFuture 的异常处理容易写错,因为同一个异常在不同入口会换不同的包装。这篇逐项把包装规则、沉默的失败、几个回调的语义、allOf / anyOf 的失败时机,以及取消与超时的实际效果都量了一遍。',
    [('CompletionException', 'supplyAsync / thenApply 里抛出的异常在 handle、exceptionally、join 里的形状(原始异常在 getCause())'), ('1006 ms vs 100 ms', 'allOf 在一个任务 100 ms 失败时,抛出异常的时刻'), ('true / 照常跑完', 'cancel(true) 返回 true 后,底层任务的状态:没有被中断,600 ms 后仍然执行完')],
    [('异常的包装', None), ('沉默的异常', None), ('whenComplete / handle', None), ('allOf 与 anyOf', None), ('取消与超时', None)],
    steps, [ENV_J + '。JDK 21.0.12;默认执行器是 ForkJoinPool.commonPool;所有任务都是自写的 sleep 与抛异常的最小任务', '没有验证:JDK 8 / 11 / 17 上包装规则的差异(这里只在 JDK 21 上运行)、orTimeout 的内部定时线程、自定义 Executor 下异常的堆栈、Reactor / RxJava 的错误处理对比'], 'CompletableFuture 异常传播')
